@startuml

class Location {
  + Address : string
}

class Driver {
  + FirstName : string
  + LastName : string
}

class Vehicle {
  + VehicleNumber : string
}

class Truck extends Vehicle {
  + Weight : int
}

class Car extends Vehicle {
  + Seats : int
}

class Van extends Vehicle {}

class Order {
  + Origin : string
  + Destination : string
  + ExecutionDate : date
}

Location "1" *-- "*" Driver
Location "1" *-- "*" Vehicle
Location "1" -- "1" Location : origin
Location "1" -- "1" Location : destination
Driver "1" -- "0..1" Order : carries out
Driver "1" -- "0..1" Vehicle : drives
Order "*" -- "1..*" Driver : assigned to

@enduml

